/* Generated by scripts/build-fallback.php — edit resources/js/signin.js instead. */
/*
 * The sign-in screen's two small pieces of behaviour.
 *
 * Everything here is an enhancement. With scripts blocked the form is an
 * ordinary form: it posts, the server answers, the page reloads with the error
 * on it, and the only thing missing is the eye button — which is why that
 * button ships hidden and is revealed from here.
 *
 * The button's three states are the point. Pressing Sign in and watching
 * nothing happen for a second is the moment somebody presses it again, so it
 * says what it is doing: idle, sending, done.
 */
(function () {
    'use strict';

    var form = document.querySelector('[data-signin]');

    if (!form) {
        return;
    }

    var button = form.querySelector('[data-signin-go]');
    var label = form.querySelector('[data-signin-label]');
    var problem = form.querySelector('[data-signin-error]');
    var eye = form.querySelector('[data-signin-eye]');
    var password = form.querySelector('#password');

    /* ── Show the password ─────────────────────────────────────────────── */
    if (eye && password) {
        eye.hidden = false;

        eye.addEventListener('click', function () {
            var hiding = password.type === 'password';

            password.type = hiding ? 'text' : 'password';
            eye.setAttribute('aria-label', hiding ? 'Hide password' : 'Show password');

            // Put the caret back where it was: retyping a password because a
            // button moved the cursor is a small thing that feels broken.
            password.focus();
            password.setSelectionRange(password.value.length, password.value.length);
        });
    }

    if (!button || !label) {
        return;
    }

    function say(text, state) {
        label.textContent = text;
        button.setAttribute('data-state', state);
    }

    function fail(message) {
        if (problem) {
            problem.textContent = message;
            problem.classList.remove('nv-hidden');
        }

        say('Sign in', 'idle');
        button.disabled = false;
    }

    /*
     * The form is posted from here rather than by the browser, for one reason:
     * the browser cannot show the result. It leaves the page the moment it
     * posts, so "Signed in" would never be seen and a wrong password would
     * arrive as a whole page reload. Posting it here means the answer comes
     * back to a page that is still standing.
     *
     * Laravel answers an XHR the same way it answers anything else — a 422 with
     * the messages on it when validation fails, a redirect when it does not —
     * so nothing on the server had to change to make this work.
     */
    form.addEventListener('submit', function (event) {
        if (!window.fetch || !window.FormData) {
            return; // Let the browser do it the ordinary way.
        }

        event.preventDefault();

        if (button.disabled) {
            return;
        }

        button.disabled = true;
        say('Signing in…', 'sending');

        if (problem) {
            problem.classList.add('nv-hidden');
        }

        fetch(form.action, {
            method: 'POST',
            body: new FormData(form),
            credentials: 'same-origin',
            headers: {
                'X-Requested-With': 'XMLHttpRequest',
                Accept: 'application/json, text/html',
            },
        })
            .then(function (response) {
                if (response.status === 422) {
                    return response.json().then(function (body) {
                        var errors = (body && body.errors) || {};
                        var first = Object.keys(errors)[0];

                        fail(first ? errors[first][0] : 'Those details were not accepted.');
                    });
                }

                if (response.status === 419) {
                    // The session expired while the page sat open. Reloading
                    // gets a fresh token, which is the only cure.
                    window.location.reload();

                    return;
                }

                if (!response.ok) {
                    fail('Something went wrong signing you in. Please try again.');

                    return;
                }

                /*
                 * A redirect that fetch followed for us: response.url is where
                 * it ended up, which is where the browser should go too. The
                 * pause is not for the computer — it is so the tick is seen.
                 */
                say('Signed in', 'done');

                var next = response.redirected ? response.url : '/';

                window.setTimeout(function () {
                    window.location.assign(next);
                }, 550);
            })
            .catch(function () {
                fail('Could not reach the server. Check your connection and try again.');
            });
    });
})();
